'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const N = input[idx++];
const M = input[idx++];
const K = input[idx++];

const waterways = [];
const roads = [];

for (let i = 0; i < M; i++) {
  const a = input[idx++] - 1;
  const b = input[idx++] - 1;
  const type = input[idx++];
  if (type === 1) waterways.push([a, b]);
  else roads.push([a, b]);
}

const parent = new Int32Array(N);
const size = new Int32Array(N);
for (let i = 0; i < N; i++) {
  parent[i] = i;
  size[i] = 1;
}

function find(x) {
  while (parent[x] !== x) {
    parent[x] = parent[parent[x]];
    x = parent[x];
  }
  return x;
}

function union(a, b) {
  let ra = find(a);
  let rb = find(b);
  if (ra === rb) return false;
  if (size[ra] < size[rb]) [ra, rb] = [rb, ra];
  parent[rb] = ra;
  size[ra] += size[rb];
  return true;
}

let possible = true;

for (const [a, b] of waterways) {
  if (!union(a, b)) possible = false;
}

let removedRoads = 0;
for (const [a, b] of roads) {
  if (!union(a, b)) removedRoads++;
}

console.log(possible && removedRoads <= K ? 'S' : 'N');
